result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tests/test_roundtrip.py", "content": "import sys
from pathlib import Path

import numpy as np
import pandas as pd
import pytest

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from tidy import DATA_PATH, SCORE_COLS, TIDY_COLUMNS, load_wide, tidy  # noqa: E402
from widen import WIDE_COLUMNS, widen  # noqa: E402


@pytest.fixture(scope="module")
def orig() -> pd.DataFrame:
    return pd.read_csv(DATA_PATH)


@pytest.fixture(scope="module")
def long_df(orig: pd.DataFrame) -> pd.DataFrame:
    return tidy(orig)


def normalize(df: pd.DataFrame) -> pd.DataFrame:
    """Bring a wide frame to canonical dtypes so both sides compare exactly."""
    df = df.copy()
    for col in df.columns:
        if col.endswith("_score"):
            df[col] = pd.to_numeric(df[col]).astype("float64")
        elif col.endswith("_date"):
            df[col] = pd.to_datetime(df[col])
        else:
            df[col] = df[col].astype("int64")
    return df.reset_index(drop=True)


def test_tidy_shape_and_columns(long_df: pd.DataFrame) -> None:
    assert list(long_df.columns) == TIDY_COLUMNS
    n_missing_test3 = int((pd.read_csv(DATA_PATH)[SCORE_COLS[2]].isna()).sum())
    expected_rows = 25 * 3 - n_missing_test3
    assert len(long_df) == expected_rows


def test_tidy_dtypes_exact(long_df: pd.DataFrame, orig: pd.DataFrame) -> None:
    assert long_df["student_id"].dtype == np.dtype("int64")
    assert long_df["test_number"].dtype == np.dtype("int64")
    assert str(long_df["score"].dtype) == "Int64"
    assert str(long_df["date"].dtype) == "datetime64[ns]"
    # Every student appears exactly once per (test_number) they took.
    counts = long_df.groupby(["student_id", "test_number"]).size()
    assert (counts == 1).all()
    assert set(long_df["test_number"].unique()) <= {1, 2, 3}


def test_missing_test3_students_have_two_rows(long_df: pd.DataFrame, orig: pd.DataFrame) -> None:
    missing = orig.loc[orig["test3_score"].isna(), "student_id"]
    assert not missing.empty
    for sid in missing:
        rows = long_df.loc[long_df["student_id"] == sid]
        assert len(rows) == 2
        assert sorted(rows["test_number"]) == [1, 2]
    # And no one else was dropped.
    for sid in set(orig["student_id"]) - set(missing):
        assert len(long_df.loc[long_df["student_id"] == sid]) == 3


def test_roundtrip_equals_original(orig: pd.DataFrame) -> None:
    result = widen(tidy(orig))
    assert list(result.columns) == WIDE_COLUMNS
    pd.testing.assert_frame_equal(
        normalize(result),
        normalize(orig),
        check_dtype=True,
        check_exact=True,
    )


def test_widen_rejects_bad_frame() -> None:
    with pytest.raises(ValueError):
        widen(pd.DataFrame({"nope": [1]}))
"})
